   585  /**
   586   *  convert msgpack to JSON string.
   587   *  This API is similar to snprintf.
   588   *
   589   *  @param  json_str  The buffer to fill JSON string.
   590   *  @param  json_size The size of json_str.
   591   *  @param  data      The msgpack_unpacked data.
   592   *  @return success   ? a number characters filled : negative value
   593   */
   594  int flb_msgpack_to_json(char *json_str, size_t json_size,
   595                          const msgpack_object *obj)
   596  {
   597      int ret = -1;
   598      int off = 0;
   599
   600      if (json_str == NULL || obj == NULL) {
   601          return -1;
   602      }
   603
   604      ret = msgpack2json(json_str, &off, json_size - 1, obj);
   605      json_str[off] = '\0';
   606      return ret ? off: ret;
   607  }
