   609  flb_sds_t flb_msgpack_raw_to_json_sds(const void *in_buf, size_t in_size)
   610  {
   611      int ret;
   612      size_t off = 0;
   613      size_t out_size;
   614      msgpack_unpacked result;
   615      msgpack_object *root;
   616      flb_sds_t out_buf;
   617      flb_sds_t tmp_buf;
   618
   619      out_size = in_size * 1.5;
   620      out_buf = flb_sds_create_size(out_size);
   621      if (!out_buf) {
   622          flb_errno();
   623          return NULL;
   624      }
   625
   626      msgpack_unpacked_init(&result);
   627      msgpack_unpack_next(&result, in_buf, in_size, &off);
   628      root = &result.data;
   629
   630      while (1) {
   631          ret = flb_msgpack_to_json(out_buf, out_size, root);
   632          if (ret <= 0) {
   633              tmp_buf = flb_sds_increase(out_buf, 256);
   634              if (tmp_buf) {
   635                  out_buf = tmp_buf;
   636                  out_size += 256;
   637              }
   638              else {
   639                  flb_errno();
   640                  flb_sds_destroy(out_buf);
   641                  msgpack_unpacked_destroy(&result);
   642                  return NULL;
   643              }
   644          }
   645          else {
   646              break;
   647          }
   648      }
   649
   650      msgpack_unpacked_destroy(&result);
   651      flb_sds_len_set(out_buf, ret);
   652
   653      return out_buf;
   654  }
